# Inputs are constructed within the stated limits and preserve problem-specific invariants.
import random


def generate(seed=0):
    r = random.Random(seed)
    vals = {("aaabcbbcc", 3), ("abcd", 2), ("a", 5)}
    while len(vals) < 600:
        n = r.randint(1, 120)
        alpha = "abcde"[: r.randint(1, 5)]
        vals.add(("".join(r.choice(alpha) for _ in range(n)), r.randint(1, 30)))
    calls = [f"candidate(s={s!r}, count={c})" for s, c in vals]
    calls.append(
        "candidate(s='', count=1)"
    )
    assert 500 <= len(calls) <= 999
    assert len(calls) == len(set(calls))
    return calls
